\begin{figure}[H]
\centering
\begin{tikzpicture}[x=1cm,y=1cm]
\node[sys box,text width=3.55cm,minimum height=1.5cm] (freeze) at (0,0) {\textbf{1. Freeze inputs}\\Manuscripts, statements\\and source records};
\node[sys box,text width=3.55cm,minimum height=1.5cm] (write) at (4.75,0) {\textbf{2. Propose revisions}\\Wording, organisation,\\examples and figures};
\node[sys box,text width=3.55cm,minimum height=1.5cm] (review) at (9.5,0) {\textbf{3. Check and review}\\Source checks;\\meaning, scope and credit};
\node[sys box,text width=3.55cm,minimum height=1.5cm] (record) at (0,-2.8) {\textbf{6. Record outcome}\\Accepted changes,\\lessons and limitations};
\node[sys box,text width=3.55cm,minimum height=1.5cm] (render) at (4.75,-2.8) {\textbf{5. Render and inspect}\\Regenerate evidence,\\PDFs and reading links};
\node[sys box,text width=3.55cm,minimum height=1.5cm] (bind) at (9.5,-2.8) {\textbf{4. Integrate changes}\\Restore authored text;\\update source bindings};
\draw[sys arrow] (freeze)--(write);
\draw[sys arrow] (write)--(review);
\draw[sys arrow] (review)--node[sys label,right,fill=none]{if accepted} (bind);
